/* Cybersecurity — L0 Fondamenti: 6 lezioni approfondite (approccio difensivo ed educativo). */
(function (ST) {
  'use strict';
  const C = ST.content, { mc, fill, order } = C;

  /* ---------- 1 · Triade CIA e minacce ---------- */
  C.addTopic({
    id: 'cyb-triade-cia-e-minacce', subject: 'cyb', stage: 'L0', minutes: 12,
    title: 'Triade CIA, minacce e principi di difesa',
    summary: 'Riservatezza, integrità, disponibilità; asset, minacce, vulnerabilità e rischio; difesa in profondità e privilegio minimo.',
    objectives: ['Spiegare la triade CIA e collegarla a esempi concreti', 'Distinguere asset, minaccia, vulnerabilità e rischio', 'Applicare difesa in profondità e privilegio minimo'],
    pages: [
      { h: 'La triade CIA', b: `La sicurezza delle informazioni si misura su tre proprietà, riassunte nella **triade CIA**.\n\n- **Riservatezza** (confidentiality): solo chi è autorizzato può leggere i dati.\n- **Integrità**: i dati non vengono modificati in modo non autorizzato o accidentale.\n- **Disponibilità** (availability): sistemi e dati sono accessibili quando servono.\n\nOgni incidente intacca almeno una delle tre.\n\n> Un database clienti copiato da un estraneo: perdita di **riservatezza**.\n> Un IBAN cambiato in una fattura: perdita di **integrità**.\n> Un ospedale con i sistemi bloccati da un ransomware: perdita di **disponibilità**.\n\nLe tre proprietà possono entrare in tensione: cifrare tutto con chiavi complicate aumenta la riservatezza ma, se si perde la chiave, i dati diventano indisponibili. Per questo si decide **quale proprietà pesa di più** per ciascun sistema.` },
      { h: 'Autenticità e non ripudio', b: `Alla triade si affiancano altre proprietà, importanti soprattutto nelle comunicazioni e nei documenti.\n\n- **Autenticità**: si può verificare che un messaggio o un utente siano davvero quello che dichiarano di essere.\n- **Non ripudio** (non-repudiation): chi ha compiuto un'azione non può negare in seguito di averla compiuta, perché esistono prove affidabili.\n- **Responsabilità** (accountability): ogni azione è riconducibile a una identità, tramite log e account personali.\n\n> Una firma digitale qualificata su un contratto garantisce **integrità** (il testo non è stato alterato), **autenticità** (il firmatario è identificato) e **non ripudio**.\n\nUn account condiviso da cinque persone distrugge la responsabilità: nei log compare «admin», non chi ha agito. Per questo si preferiscono account **nominativi**.` },
      { h: 'Asset, minacce, vulnerabilità, rischio', b: `Quattro termini da non confondere.\n\n- **Asset**: ciò che ha valore per l'organizzazione (dati, server, reputazione, persone, processi).\n- **Minaccia**: qualcosa o qualcuno che può causare un danno (un criminale, un guasto, un incendio, un errore umano).\n- **Vulnerabilità**: una debolezza che la minaccia può sfruttare (software non aggiornato, password debole, mancanza di backup).\n- **Rischio**: la possibilità che una minaccia sfrutti una vulnerabilità causando un danno a un asset, valutata per probabilità e impatto.\n\n> Asset: il gestionale dello studio. Minaccia: ransomware. Vulnerabilità: sistema senza aggiornamenti. Rischio: blocco del gestionale per giorni.\n\nSe manca la minaccia o la vulnerabilità, il rischio si riduce: una falla in un sistema isolato e non raggiungibile pesa molto meno.` },
      { h: 'Chi attacca e perché', b: `Gli attori delle minacce (**threat actors**) hanno obiettivi e mezzi diversi.\n\n- **Criminalità organizzata**: motivazione economica (ransomware, frodi, furto di carte).\n- **Hacktivisti**: motivazione ideologica o politica, spesso attacchi dimostrativi.\n- **Stati e gruppi sponsorizzati** (APT): spionaggio e sabotaggio, risorse elevate, azioni lunghe e mirate.\n- **Insider**: dipendenti o fornitori con accessi legittimi; per rancore, guadagno o semplice **errore**.\n- **Dilettanti** (cosiddetti script kiddie): usano strumenti altrui, spesso senza capirli.\n\nLa maggior parte degli attacchi non è personale: i criminali puntano a chi è **facile** da colpire, non a chi è importante. Conoscere la motivazione aiuta a prevedere cosa verrà preso di mira: dati di pagamento, proprietà intellettuale, o la semplice capacità di bloccare un'attività per chiedere un riscatto.` },
      { h: 'Superficie di attacco', b: `La **superficie di attacco** è l'insieme di tutti i punti da cui un attaccante potrebbe tentare di entrare o estrarre dati.\n\nComprende:\n- servizi esposti su Internet (siti, VPN, pannelli di amministrazione);\n- account e credenziali, comprese quelle dimenticate;\n- software installato e le sue librerie;\n- dispositivi, porte USB, reti Wi-Fi;\n- **persone**, raggiungibili con email e telefonate;\n- fornitori e servizi di terze parti.\n\nLa regola pratica è **ridurla**: ogni servizio inutile spento, ogni account non più usato disattivato, ogni software dismesso rimosso è un punto d'ingresso in meno.\n\n> Un vecchio server di test dimenticato, raggiungibile da Internet e mai aggiornato, è un esempio classico di superficie di attacco che nessuno sorveglia.\n\nNon si può difendere ciò che non si sa di avere: un **inventario** aggiornato è il primo passo.` },
      { h: 'Difesa in profondità', b: `Nessuna misura è infallibile. La **difesa in profondità** (defence in depth) mette più livelli di protezione indipendenti, in modo che il cedimento di uno non basti a compromettere tutto.\n\nLivelli tipici:\n- **fisico**: porte, badge, armadi chiusi;\n- **perimetro e rete**: firewall, segmentazione;\n- **dispositivo**: aggiornamenti, antimalware/EDR, cifratura del disco;\n- **applicazione**: validazione degli input, aggiornamenti;\n- **dati**: cifratura, backup;\n- **persone e processi**: formazione, procedure, controlli.\n\n> Una email di phishing supera il filtro antispam (livello 1), ma l'utente ha la MFA attiva (livello 2), il PC ha un EDR che blocca l'allegato (livello 3) e un backup permette il ripristino (livello 4).\n\nI livelli devono essere **diversi** tra loro: due controlli che falliscono per la stessa causa contano come uno.` },
      { h: 'Privilegio minimo e separazione', b: `Il **principio del privilegio minimo** stabilisce che ogni utente, programma o servizio riceve **solo i permessi indispensabili** per il suo compito, e solo per il tempo necessario.\n\n> Una segretaria non ha bisogno dei diritti di amministratore: se il suo account viene compromesso, l'attaccante eredita pochi poteri.\n\nPrincipi collegati:\n- **separazione dei compiti**: chi richiede un pagamento non è chi lo approva;\n- **need to know**: si accede alle informazioni solo se serve per il lavoro;\n- **revisione periodica** dei permessi, per togliere quelli accumulati cambiando mansione;\n- **account separati**: uno ordinario per l'uso quotidiano, uno amministrativo solo quando serve.\n\nIl privilegio minimo non impedisce gli incidenti, ma ne **limita il raggio d'azione**: un errore o una compromissione colpiscono meno cose. È uno dei controlli con il miglior rapporto tra costo ed efficacia.` }
    ],
    exercises: [
      mc('Un attaccante modifica di nascosto l\'importo di un bonifico in archivio. Quale proprietà è violata?', ['Integrità', 'Riservatezza', 'Disponibilità', 'Non ripudio'], 0, 'I dati sono stati alterati senza autorizzazione.'),
      mc('Un attacco che rende un sito irraggiungibile colpisce soprattutto:', ['La disponibilità', 'La riservatezza', 'L\'integrità', 'L\'autenticità'], 0, 'Il servizio non è più accessibile quando serve.'),
      mc('Quale elemento è una vulnerabilità?', ['Un server senza aggiornamenti di sicurezza', 'Un gruppo criminale organizzato che prende di mira il settore', 'Il database clienti conservato nel data center', 'La perdita economica subita dopo un incidente'], 0, 'È una debolezza sfruttabile; gli altri sono minaccia, asset e impatto.'),
      mc('La proprietà che impedisce di negare di aver eseguito un\'azione è:', ['Il non ripudio', 'La riservatezza', 'La disponibilità', 'Il privilegio minimo'], 0, 'Si basa su prove affidabili come firme e log.'),
      fill('Il principio per cui si concedono solo i permessi indispensabili si chiama privilegio ...', ['minimo'], 'Privilegio minimo (least privilege).'),
      order('Ordina la catena logica del rischio', ['minaccia', 'sfrutta', 'vulnerabilità', 'di un', 'asset', 'causando danno'], 'Una minaccia sfrutta una vulnerabilità di un asset causando un danno.'),
      mc('Perché un account «admin» condiviso da più persone è un problema?', ['Si perde la responsabilità individuale nei log', 'Rende il sistema più lento a ogni accesso contemporaneo', 'Impedisce di attivare la cifratura dei dati sul server', 'Aumenta la disponibilità del servizio per tutti gli utenti'], 0, 'Non si può attribuire l\'azione a una persona.'),
      mc('Quale esempio è un insider?', ['Un dipendente scontento con accesso legittimo', 'Un gruppo hacktivista esterno all’organizzazione', 'Un virus diffuso tramite messaggi di posta elettronica', 'Un guasto elettrico nella sala server aziendale'], 0, 'L\'insider ha già accessi legittimi.'),
      mc('Quale azione riduce la superficie di attacco?', ['Spegnere un servizio esposto e non più necessario', 'Aggiungere account di prova per i nuovi collaboratori', 'Aprire più porte nel firewall per i fornitori esterni', 'Condividere le password tra i membri di un reparto'], 0, 'Meno punti d\'ingresso, meno opportunità.'),
      fill('Più livelli di protezione indipendenti formano la difesa in ...', ['profondità'], 'Defence in depth.'),
      mc('Quale scelta rispetta la separazione dei compiti?', ['Chi richiede un pagamento non lo approva', 'Una sola persona richiede e approva i pagamenti', 'Tutti i colleghi conoscono la password del conto', 'L\'approvazione dei pagamenti avviene in automatico'], 0, 'Serve un secondo controllo indipendente.')
    ],
    test: [
      mc('Un ospedale non riesce ad accedere alle cartelle cliniche perché i sistemi sono cifrati dal malware. Quale proprietà è colpita per prima?', ['Disponibilità', 'Riservatezza', 'Autenticità', 'Non ripudio'], 0, 'Le cartelle non sono accessibili quando servono.'),
      mc('Dati personali pubblicati online da un estraneo violano:', ['La riservatezza', 'La disponibilità', 'L\'integrità', 'La separazione dei compiti'], 0, 'Accesso a informazioni non autorizzato.'),
      mc('Quale coppia è corretta?', ['Minaccia: ransomware; vulnerabilità: assenza di backup', 'Minaccia: password debole; vulnerabilità: criminale', 'Asset: phishing; minaccia: server', 'Rischio: firewall; asset: hacker'], 0, 'Il ransomware è l\'agente, l\'assenza di backup la debolezza.'),
      mc('Gli attaccanti con motivazione soprattutto economica sono tipicamente:', ['La criminalità organizzata', 'Gli attivisti (hacktivisti)', 'Gli auditor interni', 'I fornitori di antivirus'], 0, 'Ransomware e frodi mirano al profitto.'),
      mc('Perché due controlli basati sulla stessa causa di fallimento valgono come uno?', ['Falliscono insieme, quindi non sono livelli indipendenti', 'Costano il doppio senza offrire una protezione davvero maggiore', 'Rallentano la rete più di quanto proteggano i sistemi', 'Non sono ammessi dagli standard di sicurezza vigenti'], 0, 'La difesa in profondità richiede livelli diversi.'),
      order('Ordina un esempio di difesa a livelli', ['filtro email', 'MFA', 'EDR sul PC', 'backup'], 'Dal primo ostacolo fino al ripristino.'),
      fill('L\'insieme dei punti da cui si può tentare un ingresso è la superficie di ...', ['attacco'], 'Attack surface.')
    ]
  });

  /* ---------- 2 · Gestione del rischio ---------- */
  C.addTopic({
    id: 'cyb-gestione-del-rischio', subject: 'cyb', stage: 'L0', minutes: 12,
    prereq: ['cyb-triade-cia-e-minacce'],
    title: 'Gestione del rischio',
    summary: 'Probabilità per impatto, matrice qualitativa, strategie di trattamento e tipi di controlli.',
    objectives: ['Calcolare e classificare un rischio con probabilità e impatto', 'Scegliere tra ridurre, trasferire, evitare e accettare', 'Distinguere controlli preventivi, di rilevamento e correttivi'],
    pages: [
      { h: 'Perché si gestisce il rischio', b: `Non si può azzerare il rischio né proteggere tutto allo stesso modo: il budget, il tempo e le persone sono limitati. La **gestione del rischio** serve a decidere **dove investire** per primo.\n\nIl processo ha quattro passi ripetuti nel tempo:\n1. **identificare** asset, minacce e vulnerabilità;\n2. **valutare** probabilità e impatto di ogni rischio;\n3. **trattare** i rischi con una strategia e dei controlli;\n4. **monitorare** e rivedere, perché minacce e sistemi cambiano.\n\n> Un piccolo studio professionale scopre che i dati dei clienti stanno su un solo PC senza copie: il rischio di perdita è alto e il rimedio è economico, quindi ha priorità sulla compra di un firewall costoso.\n\nLa gestione del rischio è un ciclo continuo, non un documento da scrivere una volta.` },
      { h: 'Rischio = probabilità × impatto', b: `Il rischio si stima combinando due fattori.\n\n- **Probabilità** (likelihood): quanto è verosimile che l'evento accada in un dato periodo.\n- **Impatto**: quanto è grave il danno se accade (economico, legale, operativo, reputazionale).\n\n**Rischio = probabilità × impatto**\n\n> Un evento con probabilità 10% all'anno e danno di 50.000 € ha una perdita attesa di 0,10 × 50.000 = **5.000 € l'anno**.\n\nQuesta perdita annua attesa aiuta a confrontare: spendere 1.000 € l'anno per ridurla a 500 € è conveniente; spenderne 8.000 € no.\n\nAttenzione: le stime sono **incerte**. Un evento raro ma catastrofico (probabilità bassa, impatto enorme) può meritare attenzione quanto uno frequente ma lieve, anche se il prodotto numerico è simile. I numeri guidano il giudizio, non lo sostituiscono.` },
      { h: 'Matrice qualitativa', b: `Quando mancano dati precisi si usa una valutazione **qualitativa**: probabilità e impatto su una scala, per esempio da 1 (basso) a 3 (alto), incrociate in una **matrice**.\n\n- Punteggio 1–2: rischio **basso**.\n- Punteggio 3–4: rischio **medio**.\n- Punteggio 6–9: rischio **alto**.\n\n> Phishing verso i dipendenti: probabilità 3, impatto 2 → **6, alto**.\n> Incendio nella sala server: probabilità 1, impatto 3 → **3, medio**.\n> Refuso sul sito: probabilità 3, impatto 1 → **3, medio**.\n\nLa matrice ordina i rischi per priorità in modo semplice e condivisibile. Limiti: scale soggettive, e persone diverse assegnano punteggi diversi. Per ridurre il problema si definiscono criteri chiari (per esempio «impatto alto = oltre 100.000 € o sospensione dell'attività oltre 3 giorni») e si valuta in gruppo.` },
      { h: 'Le quattro strategie di trattamento', b: `Per ogni rischio si sceglie una risposta.\n\n- **Ridurre** (mitigare): applicare controlli che abbassano probabilità o impatto.\n- **Trasferire** (condividere): spostare parte delle conseguenze su altri, per esempio con un'**assicurazione** informatica o con un fornitore in outsourcing contrattualizzato.\n- **Evitare**: eliminare l'attività che genera il rischio.\n- **Accettare**: decidere consapevolmente di convivere con il rischio, di solito perché è basso o il rimedio costa troppo.\n\n> Raccogliere dati sanitari che non servono: si **evita** smettendo di raccoglierli.\n> Rischio di sanzioni o costi di ripristino: in parte si **trasferisce** con una polizza.\n\nL'accettazione deve essere **documentata e approvata** da chi ha l'autorità di farlo; ignorare un rischio per mancata conoscenza non è accettarlo. Trasferire non elimina la responsabilità verso clienti e autorità: i dati restano comunque dell'organizzazione.` },
      { h: 'Controlli preventivi, di rilevamento, correttivi', b: `I **controlli** sono le misure che trattano il rischio. Per funzione si distinguono tre famiglie.\n\n- **Preventivi**: impediscono l'evento. Esempi: MFA, privilegio minimo, aggiornamenti, serrature, formazione.\n- **Di rilevamento** (detective): segnalano che qualcosa sta accadendo o è accaduto. Esempi: log centralizzati, allarmi, telecamere, monitoraggio degli accessi anomali.\n- **Correttivi**: limitano il danno e ripristinano. Esempi: backup e ripristino, piano di risposta agli incidenti, isolamento di un PC infetto.\n\nSi aggiungono i controlli **deterrenti** (cartelli, avvisi di monitoraggio) e **compensativi** (misure alternative quando quella ideale non è possibile).\n\n> Un ransomware: il patching è **preventivo**, l'EDR che avvisa è di **rilevamento**, il backup offline è **correttivo**.\n\nUn buon programma usa tutte e tre le famiglie, perché la prevenzione prima o poi fallisce.` },
      { h: 'Controlli tecnici, organizzativi, fisici', b: `Un'altra classificazione guarda **la natura** del controllo.\n\n- **Tecnici**: implementati da software o hardware (cifratura, firewall, MFA, antimalware).\n- **Organizzativi** o amministrativi: politiche, procedure, formazione, gestione dei fornitori, ruoli e responsabilità.\n- **Fisici**: porte, badge, videosorveglianza, armadi chiusi, gruppi di continuità.\n\nLe due classificazioni si incrociano: la formazione è un controllo organizzativo e preventivo; il log degli accessi è tecnico e di rilevamento.\n\n> Una procedura che impone una seconda approvazione per i bonifici oltre 5.000 € è un controllo **organizzativo preventivo** che neutralizza molte truffe del falso fornitore, senza alcuna tecnologia.\n\nI controlli hanno anche un **costo** e un effetto sull'usabilità. Una misura troppo scomoda viene aggirata dalle persone: la sicurezza efficace tiene conto di come lavorano davvero gli utenti.` },
      { h: 'Esempio numerico completo', b: `Una piccola azienda valuta il rischio **ransomware sul file server**.\n\n- Impatto stimato: 4 giorni fermi e ripristino = **80.000 €**.\n- Probabilità stimata: **15% all'anno**.\n- Perdita annua attesa: 0,15 × 80.000 = **12.000 €**.\n\nOpzioni:\n- **A**: backup offline + patching + MFA, costo 3.000 € l'anno. Riducono la probabilità al 5% e l'impatto a 20.000 € (ripristino rapido). Nuova perdita attesa: 0,05 × 20.000 = **1.000 €**.\n- **B**: assicurazione da 2.500 € l'anno che copre metà del danno, senza altre misure.\n\nPer A: riduzione 12.000 − 1.000 = 11.000 €, costo 3.000 €, **beneficio netto circa 8.000 €**.\n\nLa scelta ragionevole è **A**, eventualmente con una polizza per il **rischio residuo**. Il rischio residuo è ciò che rimane dopo i controlli: va sempre accettato o trasferito esplicitamente.` },
      { h: 'Rischio inerente, residuo e registro', b: `Due concetti completano il quadro.\n\n- **Rischio inerente**: il livello prima di applicare qualsiasi controllo.\n- **Rischio residuo**: il livello che rimane dopo i controlli. Non è mai zero.\n\nL'organizzazione fissa una **soglia di tolleranza** (risk appetite): i rischi residui sopra la soglia richiedono altre azioni.\n\nTutto si annota in un **registro dei rischi** con, per ogni voce: descrizione, asset, probabilità, impatto, controlli esistenti, strategia scelta, **responsabile** (risk owner), scadenza e stato.\n\n> «Perdita del portatile del commerciale: probabilità media, impatto alto per i dati; controllo: cifratura del disco; responsabile: IT; rischio residuo: basso.»\n\nIl registro va **rivisto** a intervalli regolari e dopo ogni cambiamento importante (nuovo fornitore, nuovo sistema, incidente). Un rischio senza responsabile di solito non viene trattato da nessuno.` }
    ],
    exercises: [
      mc('Se la probabilità annua è 20% e l\'impatto è 10.000 €, la perdita annua attesa è:', ['2.000 €', '200 €', '10.000 €', '50.000 €'], 0, '0,20 × 10.000 = 2.000.'),
      mc('Sottoscrivere un\'assicurazione informatica è una strategia di:', ['Trasferimento', 'Evitamento', 'Accettazione', 'Rilevamento'], 0, 'Si sposta parte delle conseguenze economiche su un terzo.'),
      mc('Smettere di raccogliere un dato non necessario per eliminare il relativo rischio significa:', ['Evitare il rischio', 'Accettarlo', 'Trasferirlo', 'Rilevarlo'], 0, 'Si elimina l\'attività che genera il rischio.'),
      mc('Un backup offline testato è un controllo:', ['Correttivo', 'Deterrente', 'Preventivo puro', 'Di rilevamento'], 0, 'Serve a ripristinare dopo l\'evento.'),
      mc('Un allarme che avvisa di accessi anomali è un controllo:', ['Di rilevamento', 'Correttivo', 'Preventivo', 'Fisico per definizione'], 0, 'Segnala che qualcosa accade.'),
      fill('Il rischio che rimane dopo l\'applicazione dei controlli è il rischio ...', ['residuo'], 'Rischio residuo.'),
      order('Ordina il ciclo di gestione del rischio', ['identificare', 'valutare', 'trattare', 'monitorare'], 'Il ciclo si ripete nel tempo.'),
      mc('Nella matrice 1–3 un rischio con probabilità 3 e impatto 3 vale:', ['9, alto', '6, medio', '3, basso', '1, basso'], 0, '3 × 3 = 9.'),
      mc('Quale affermazione sull\'accettazione del rischio è corretta?', ['Deve essere consapevole, documentata e approvata', 'Significa ignorare il problema', 'È vietata per legge', 'Elimina ogni responsabilità'], 0, 'Accettare è una decisione, non una dimenticanza.'),
      fill('Un\'unica voce del registro dei rischi ha un responsabile detto risk ...', ['owner', 'Owner', 'proprietario'], 'Il risk owner risponde del trattamento.'),
      mc('La doppia approvazione dei bonifici oltre una soglia è un controllo:', ['Organizzativo e preventivo', 'Tecnico e correttivo', 'Fisico e di rilevamento', 'Deterrente e tecnico'], 0, 'È una procedura che previene frodi.')
    ],
    test: [
      mc('Probabilità annua 5% e danno di 40.000 €: la perdita attesa è:', ['2.000 €', '200 €', '8.000 €', '20.000 €'], 0, '0,05 × 40.000 = 2.000.'),
      mc('Con una perdita attesa di 6.000 € l\'anno, quale misura è economicamente sensata?', ['Un controllo da 1.500 € che dimezza il rischio', 'Un controllo da 9.000 € che dimezza il rischio', 'Nessuna valutazione', 'Un controllo da 7.000 € che non cambia nulla'], 0, 'Costa 1.500 e fa risparmiare 3.000.'),
      mc('L\'applicazione tempestiva degli aggiornamenti è soprattutto un controllo:', ['Preventivo', 'Di rilevamento', 'Correttivo', 'Deterrente'], 0, 'Chiude la vulnerabilità prima dello sfruttamento.'),
      mc('Il rischio prima di qualsiasi controllo si chiama:', ['Inerente', 'Residuo', 'Trasferito', 'Accettato'], 0, 'Rischio inerente.'),
      mc('Una matrice qualitativa ha come limite principale:', ['La soggettività dei punteggi', 'L\'impossibilità di ordinare i rischi', 'Il costo elevato', 'L\'uso obbligato di software'], 0, 'Per questo servono criteri chiari condivisi.'),
      order('Ordina la valutazione di un singolo rischio', ['stima probabilità', 'stima impatto', 'calcola livello', 'scegli strategia'], 'Prima i fattori, poi il livello, poi la decisione.'),
      fill('La soglia di rischio che l\'organizzazione tollera si chiama risk ...', ['appetite', 'Appetite', 'tolerance'], 'Risk appetite (propensione al rischio).')
    ]
  });

  /* ---------- 3 · Autenticazione e password ---------- */
  C.addTopic({
    id: 'cyb-autenticazione-e-password', subject: 'cyb', stage: 'L0', minutes: 12,
    title: 'Autenticazione, password e MFA',
    summary: 'Fattori, entropia delle password, hash con sale, MFA e passkey, gestori di password e difese contro il riuso delle credenziali.',
    objectives: ['Distinguere i fattori di autenticazione e la MFA resistente al phishing', 'Calcolare l\'entropia di una password e spiegare perché la lunghezza conta', 'Spiegare hash con sale, gestori di password e limiti ai tentativi'],
    pages: [
      { h: 'Identificazione, autenticazione, autorizzazione', b: `Tre passaggi distinti.\n\n- **Identificazione**: dichiaro chi sono (nome utente).\n- **Autenticazione**: dimostro che sono davvero quella persona.\n- **Autorizzazione**: il sistema decide che cosa posso fare.\n\nI **fattori di autenticazione** sono di tre tipi.\n\n- **Qualcosa che sai**: password, PIN.\n- **Qualcosa che hai**: telefono, chiave di sicurezza, smart card.\n- **Qualcosa che sei**: impronta, volto (biometria).\n\n> Prelevare al bancomat: la carta (**hai**) più il PIN (**sai**) sono due fattori diversi.\n\nDue password non sono due fattori: sono lo **stesso** fattore ripetuto. Un attaccante che scopre una cosa che sai può probabilmente scoprire anche l'altra. La forza dell'autenticazione deriva dalla **combinazione di categorie diverse**, che costringe l'attaccante a superare ostacoli di natura diversa.` },
      { h: 'Entropia: la lunghezza vince', b: `L'**entropia** misura quanto è imprevedibile una password, in **bit**: con n bit esistono 2ⁿ possibilità.\n\nSe i caratteri sono scelti a caso da un insieme di N simboli, l'entropia è **lunghezza × log₂(N)**.\n\n- Cifre (N = 10): ≈ 3,3 bit per carattere.\n- Lettere minuscole (26): ≈ 4,7 bit.\n- Minuscole + maiuscole + cifre (62): ≈ 5,95 bit.\n- Con simboli (circa 94): ≈ 6,55 bit.\n\n> 8 caratteri su 94 simboli: 8 × 6,55 ≈ **52 bit**.\n> 16 lettere minuscole casuali: 16 × 4,7 ≈ **75 bit**.\n> 4 parole scelte a caso da una lista di 7.776: 4 × 12,9 ≈ **52 bit**; con 6 parole ≈ **78 bit**.\n\nOgni bit in più **raddoppia** le possibilità. Aggiungere 8 caratteri minuscoli (+37,6 bit) fa guadagnare molto più che sostituire una lettera con un simbolo. Conta solo se la scelta è **davvero casuale**: «Password1!» ha pochi bit reali perché è prevedibile.` },
      { h: 'Perché non basta la complessità', b: `Gli attaccanti non provano combinazioni in ordine: usano **elenchi di password comuni**, parole di dizionario con le sostituzioni più diffuse (a → @, o → 0) e dati personali (nomi, date di nascita).\n\n> «Juve1897!» sembra complessa ma è molto prevedibile; una frase lunga e casuale come «bicicletta-orologio-nebbia-tavola» è molto più forte e più facile da ricordare.\n\nLe indicazioni moderne (per esempio quelle dell'ente statunitense NIST) suggeriscono di:\n- privilegiare la **lunghezza** (almeno 12–15 caratteri, meglio di più);\n- accettare **passphrase** con spazi;\n- **rifiutare** password note o comparse in violazioni di dati;\n- **non imporre** cambi periodici senza motivo, che spingono a varianti prevedibili (Password1, Password2...);\n- cambiare la password solo se c'è sospetto di compromissione.\n\nNon basta quindi «una maiuscola e un numero»: servono lunghezza, casualità e **unicità**.` },
      { h: 'Come si conservano le password: hash e sale', b: `Un sistema ben fatto **non memorizza le password**, ma la loro **impronta** (hash).\n\nUna funzione di hash trasforma un testo in una stringa di lunghezza fissa ed è **a senso unico**: dall'hash non si risale alla password. Al login il sistema calcola l'hash di quanto digitato e lo confronta con quello archiviato.\n\nSe il database viene rubato, l'attaccante prova a indovinare password candidate calcolandone l'hash. Per rallentarlo si usano:\n- il **sale** (salt): un valore casuale diverso per ogni utente, aggiunto prima dell'hash. Due utenti con la stessa password hanno hash diversi e le tabelle precalcolate diventano inutili;\n- funzioni **lente e progettate allo scopo** (come Argon2, bcrypt, scrypt), non un semplice hash veloce.\n\n> Se un sito ti invia la password in chiaro per email dopo il recupero, la sta conservando in chiaro: segnale di cattiva sicurezza. Se è così, non riusarla altrove.` },
      { h: 'MFA e passkey', b: `L'**autenticazione a più fattori** (MFA) unisce fattori di categorie diverse. Non tutte le MFA hanno la stessa forza.\n\n- **SMS**: meglio di niente, ma esposto allo scambio di SIM (SIM swap) e all'intercettazione.\n- **App con codici temporanei** (TOTP): codice a 6 cifre che cambia ogni 30 secondi; più solida, ma un sito falso può farselo digitare e inoltrarlo.\n- **Notifica push**: comoda; attenzione alla **fatica da MFA**, cioè richieste ripetute finché l'utente accetta per stanchezza. Meglio i sistemi con **number matching**.\n- **Chiavi FIDO2 / passkey**: **resistenti al phishing**. La credenziale è legata al dominio reale: su un sito falso non funziona e non c'è nulla da digitare né da rubare.\n\n> Un utente inserisce password e codice TOTP in una pagina falsa: l'attaccante li usa subito sul sito vero. Con una passkey la pagina falsa non può ottenere nulla di utilizzabile.\n\nLe passkey usano la crittografia a chiave pubblica: sul server resta solo la chiave pubblica.` },
      { h: 'Gestori di password e riuso', b: `Una password per ogni servizio è fondamentale, ma nessuno può ricordare decine di password lunghe e casuali. Il **gestore di password** risolve il problema.\n\nVantaggi:\n- genera password **casuali e uniche**;\n- le compila **solo sul dominio corretto**: se la pagina è un falso, non propone nulla, un segnale d'allarme utile;\n- richiede ricordare **una sola** password principale, che deve essere lunga e robusta e protetta da MFA.\n\nRischi e cautele: se la password principale è debole, si compromette tutto; l'archivio è cifrato localmente nei prodotti seri. Per le poche credenziali critiche (la email, il gestore) si usa MFA resistente al phishing.\n\n> Il **riuso** è il vero nemico: se la stessa password è su un forum piccolo e sulla banca, una violazione del forum apre anche la banca.\n\nControlla periodicamente se i tuoi indirizzi compaiono in violazioni note (servizi come Have I Been Pwned) e cambia subito le password coinvolte.` },
      { h: 'Credential stuffing, blocchi e limiti', b: `Il **credential stuffing** consiste nel provare, in modo automatico e su larga scala, coppie email-password rubate da una violazione su altri servizi, sperando nel **riuso**. Il **password spraying** prova poche password comuni su molti account per evitare i blocchi.\n\nLe difese dal lato del servizio:\n- **limitare i tentativi** (rate limiting) per account e per indirizzo IP;\n- **blocco temporaneo** o ritardi crescenti dopo ripetuti errori, evitando però blocchi permanenti che consentirebbero di bloccare un utente a piacere (denial of service);\n- **CAPTCHA** o controlli sui comportamenti anomali;\n- **MFA** obbligatoria, che rende inutile la sola password;\n- controllo delle password contro elenchi di credenziali violate;\n- **avvisi** all'utente sui nuovi accessi.\n\nDal lato dell'utente: password **uniche** per ogni sito, gestore di password, MFA attiva dove disponibile.\n\n> Con un servizio che consente 5 tentativi ogni 15 minuti, provare 1.000.000 di combinazioni richiederebbe oltre 5 anni su un solo account.` }
    ],
    exercises: [
      mc('Quale combinazione rappresenta davvero due fattori diversi?', ['Password e chiave di sicurezza FIDO2', 'Password e PIN', 'Due password diverse', 'Domanda segreta e password'], 0, 'Sai + hai: categorie diverse.'),
      mc('Quanta entropia ha circa una password casuale di 10 cifre?', ['Circa 33 bit', 'Circa 10 bit', 'Circa 100 bit', 'Circa 64 bit'], 0, '10 × 3,32 ≈ 33 bit.'),
      mc('Quale password casuale è più forte?', ['16 lettere minuscole (≈ 75 bit)', '8 caratteri con simboli (≈ 52 bit)', '10 cifre (≈ 33 bit)', '6 lettere minuscole (≈ 28 bit)'], 0, 'Più bit di entropia reale.'),
      fill('Un valore casuale aggiunto alla password prima dell\'hash si chiama ...', ['sale', 'salt'], 'Il sale rende diversi gli hash di password uguali.'),
      mc('Le passkey sono resistenti al phishing perché:', ['La credenziale è legata al dominio reale del sito', 'Usano un codice SMS', 'Sono più lunghe di una password', 'Sono scritte su carta'], 0, 'Un sito falso non può ottenere una risposta valida.'),
      mc('Quale è un limite della MFA con notifica push semplice?', ['La fatica da MFA: richieste ripetute fino a un\'accettazione', 'Non esiste alcun limite', 'Funziona solo offline', 'Richiede 12 caratteri'], 0, 'L\'utente può approvare per stanchezza.'),
      order('Ordina il login con hash', ['inserisci password', 'sistema aggiunge il sale', 'calcola l\'hash', 'confronta con quello archiviato'], 'Il sistema non confronta mai la password in chiaro.'),
      mc('Perché il riuso della password è pericoloso?', ['Una violazione altrove apre anche gli altri account', 'Rallenta il computer', 'Rende l\'hash reversibile', 'Annulla la MFA'], 0, 'Base del credential stuffing.'),
      mc('Quale difesa del servizio limita il credential stuffing?', ['Limitare i tentativi e imporre la MFA', 'Mostrare le password agli utenti', 'Consentire tentativi illimitati di accesso', 'Eliminare l\'hash dai dati salvati'], 0, 'Rate limiting e secondo fattore.'),
      mc('Perché un blocco permanente dopo 3 errori può essere un problema?', ['Permette di bloccare utenti legittimi a piacere', 'Aumenta l\'entropia', 'Sostituisce la MFA', 'Cifra i dati'], 0, 'Diventa un attacco di negazione del servizio.'),
      fill('Aggiungere un bit di entropia ... il numero di combinazioni.', ['raddoppia', 'duplica'], 'Ogni bit moltiplica per 2.')
    ],
    test: [
      mc('Quale fattore è «qualcosa che sei»?', ['Impronta digitale', 'PIN', 'Chiave USB', 'Password'], 0, 'È un dato biometrico.'),
      mc('Quanta entropia hanno circa 6 parole scelte a caso da 7.776 (12,9 bit l\'una)?', ['Circa 78 bit', 'Circa 13 bit', 'Circa 26 bit', 'Circa 40 bit'], 0, '6 × 12,9 ≈ 77,5.'),
      mc('Dove viene conservata, in un sistema ben progettato, la password dell\'utente?', ['Solo sotto forma di hash con sale', 'In chiaro', 'Cifrata con una chiave nota a tutti', 'Nel browser dell\'amministratore'], 0, 'Non si archivia la password.'),
      mc('Quale metodo MFA resiste meglio a una pagina di login falsa?', ['Chiave FIDO2', 'Codice via SMS', 'Domanda segreta', 'Codice TOTP digitato'], 0, 'La credenziale è legata al dominio.'),
      mc('Il password spraying consiste nel:', ['Provare poche password comuni su molti account', 'Provare milioni di password su un solo account', 'Riparare un hash', 'Cifrare l\'archivio'], 0, 'Evita i blocchi per singolo account.'),
      mc('Quale politica è oggi sconsigliata?', ['Cambio obbligatorio ogni 30 giorni senza motivo', 'Controllo contro password violate', 'Passphrase lunghe', 'MFA'], 0, 'Spinge a varianti prevedibili.'),
      order('Ordina dal meno al più robusto per lunghezza casuale', ['6 cifre', '8 caratteri con simboli', '16 minuscole', '6 parole casuali'], 'Entropia crescente circa 20, 52, 75, 78 bit.')
    ]
  });

  /* ---------- 4 · Ingegneria sociale e phishing ---------- */
  C.addTopic({
    id: 'cyb-ingegneria-sociale-e-phishing', subject: 'cyb', stage: 'L0', minutes: 12,
    title: 'Ingegneria sociale e phishing',
    summary: 'Tipi di phishing, pretexting, leve psicologiche, controlli su intestazioni, link e allegati, segnalazione e difese organizzative.',
    objectives: ['Riconoscere phishing, spear phishing, vishing, smishing e BEC', 'Individuare le leve psicologiche e i segnali tecnici', 'Sapere come segnalare e quali difese adotta un\'organizzazione'],
    pages: [
      { h: 'Che cos\'è l\'ingegneria sociale', b: `L'**ingegneria sociale** manipola le persone, anziché i sistemi, per ottenere informazioni, accessi o denaro. Funziona perché l'essere umano è spesso l'anello più semplice da aggirare: costa meno convincere un dipendente che forzare un sistema ben protetto.\n\nL'attacco tipico ha quattro fasi:\n1. **raccolta di informazioni** (siti aziendali, social, profili professionali);\n2. **costruzione di un pretesto** credibile;\n3. **contatto** e manipolazione;\n4. **azione**: la vittima rivela dati, clicca, paga o apre una porta.\n\n> Un messaggio che cita il nome del tuo responsabile e un progetto reale è credibile proprio perché le informazioni sono pubbliche.\n\nNon è una questione di intelligenza: chiunque, se stanco, di fretta o in un momento di pressione, può cadere. Per questo conta più la **procedura** che la sola attenzione individuale.` },
      { h: 'Le varianti del phishing', b: `Il **phishing** è un messaggio fraudolento che si fa passare per un mittente fidato per ottenere credenziali, dati o pagamenti.\n\n- **Phishing di massa**: stesso messaggio a migliaia di persone (finta banca, finto corriere).\n- **Spear phishing**: messaggio **su misura** per una persona o un ruolo, con dettagli reali.\n- **Whaling**: spear phishing contro i dirigenti.\n- **Vishing** (voice): telefonata, a volte con voce o numero imitati.\n- **Smishing** (SMS): messaggi di testo con link, tipici i finti «pacco in giacenza».\n- **Quishing**: codice QR che porta a un sito falso.\n- **BEC** (Business Email Compromise): email che imita un dirigente o un fornitore per far eseguire un bonifico o cambiare un IBAN. Spesso **non contiene link né allegati**, quindi i filtri tecnici la vedono poco.\n\n> «Sono in riunione, effettua subito un bonifico urgente a questo nuovo IBAN, ti spiego dopo.»` },
      { h: 'Pretexting e le leve psicologiche', b: `Il **pretexting** è la costruzione di una storia credibile (il pretesto) per giustificare una richiesta: finto tecnico informatico, finto fornitore, finto funzionario.\n\nGli attaccanti sfruttano leve psicologiche note:\n- **Autorità**: «sono il direttore generale», «sono della banca».\n- **Urgenza**: «entro un'ora o l'account sarà sospeso».\n- **Paura**: «accesso sospetto al tuo conto».\n- **Curiosità e avidità**: premi, rimborsi, foto, offerte.\n- **Fiducia e reciprocità**: un favore, una cortesia che spinge a ricambiare.\n- **Conformità sociale**: «tutti i colleghi l'hanno già fatto».\n\n> «Il suo pacco è bloccato, paghi 1,99 € di spese entro oggi.» Combina urgenza, importo piccolo e familiarità.\n\nLa difesa generale: quando un messaggio crea **fretta o emozione** e chiede di **fare qualcosa fuori dalla procedura**, fermati. È il segnale più affidabile, più di qualsiasi errore di ortografia, che i messaggi moderni spesso non contengono.` },
      { h: 'Controllare mittente, link e allegati', b: `Controlli pratici, **senza cliccare**.\n\n**Mittente.** Il nome visibile si falsifica facilmente: guarda l'**indirizzo completo**. Attenzione ai domini simili (rn al posto di m, l minuscola e I maiuscola) e al campo **Rispondi a** diverso dal mittente. Le intestazioni tecniche mostrano gli esiti di SPF, DKIM e DMARC: **fallimenti** sono sospetti, ma i passaggi non garantiscono l'onestà del contenuto.\n\n**Link.** Passa il cursore sopra per vedere la destinazione reale. Il dominio è la parte **prima del primo «/»** e letta da destra a sinistra: in «banca.example.com.sito-falso.net» il dominio vero è sito-falso.net. Diffida degli URL accorciati.\n\n**Allegati.** Cautela con estensioni insolite, documenti che chiedono di «abilitare le macro» o «abilitare il contenuto», archivi protetti da password, fatture inattese.\n\n> Nel dubbio, **non usare il link del messaggio**: apri il sito digitando l'indirizzo o con un segnalibro, o chiama il numero ufficiale.` },
      { h: 'Cosa fare e come segnalare', b: `Se ricevi un messaggio sospetto:\n1. **non cliccare**, non rispondere, non aprire allegati;\n2. **verifica** per un altro canale (telefono ufficiale, di persona);\n3. **segnala** secondo la procedura aziendale (di solito un pulsante «segnala phishing» o l'ufficio IT/sicurezza);\n4. poi elimina il messaggio.\n\nSe hai già **cliccato o inserito dati**, agisci subito e **senza vergogna**:\n- cambia la password dal sito vero e verifica la MFA;\n- avvisa IT: più si tarda, più il danno cresce;\n- se hai dato dati di pagamento, contatta la banca per bloccare carte e bonifici;\n- in caso di truffa, valuta la denuncia alla Polizia Postale.\n\nIn Italia le segnalazioni possono andare anche ai **CERT/CSIRT** nazionali. Una segnalazione **rapida** di un solo utente può proteggere tutti gli altri: lo stesso messaggio è arrivato a molti colleghi.\n\nUna cultura che punisce chi sbaglia porta a nascondere gli errori; una che ringrazia chi segnala li scopre prima.` },
      { h: 'Difese organizzative', b: `Contare solo sull'attenzione dei singoli è fragile. Le organizzazioni mettono più livelli.\n\n- **Filtri email** e protezione dei link e degli allegati.\n- **SPF, DKIM, DMARC** per rendere difficile falsificare il proprio dominio.\n- **MFA resistente al phishing** (FIDO2/passkey): anche se la password viene ceduta, l'accesso non riesce.\n- **Procedure di verifica**: richiamare il fornitore al numero già in archivio prima di cambiare un IBAN; **doppia approvazione** dei bonifici; parole d'ordine concordate.\n- **Privilegio minimo**, per limitare il danno di un account compromesso.\n- **Formazione continua**, breve e con casi reali, non una volta all'anno.\n- **Canale di segnalazione** semplice e senza colpe.\n\n> Una truffa BEC perde efficacia quando una regola dice: «Nessun IBAN cambia per email, si conferma sempre telefonando al numero già noto».\n\nL'obiettivo è rendere **la scelta sicura anche la più facile**.` },
      { h: 'Simulazioni di phishing: etica', b: `Molte organizzazioni fanno **simulazioni di phishing** per misurare la consapevolezza e addestrare. Se mal condotte fanno danni, quindi servono regole.\n\nBuone pratiche:\n- **autorizzazione formale** della direzione e coinvolgimento di legale/privacy e risorse umane;\n- **obiettivo formativo**, non punitivo: niente classifiche pubbliche, niente nomi alla berlina;\n- **pretesti rispettosi**: evitare esche che sfruttano paura per il lavoro, lutti, salute o bonus reali;\n- **nessuna raccolta di credenziali reali**: la pagina di destinazione spiega subito che era un test;\n- **rispetto della privacy** e delle norme sul trattamento dei dati, con risultati aggregati;\n- **supporto** a chi clicca, con una micro-lezione immediata;\n- misurare il **tasso di segnalazione**, non solo quello di clic.\n\n> Un click rate che scende ma un tasso di segnalazione che sale indica un reale miglioramento.\n\nSimulare su persone esterne all'organizzazione, senza autorizzazione, è un'attività illecita e non un esercizio.` }
    ],
    exercises: [
      mc('Un SMS fraudolento con un link a un falso tracciamento pacco è:', ['Smishing', 'Vishing', 'Whaling', 'Pretexting vocale'], 0, 'SMS + phishing.'),
      mc('Un messaggio costruito su misura con dettagli reali su un dipendente è:', ['Spear phishing', 'Phishing di massa', 'Spam', 'Quishing'], 0, 'Mirato a una persona o ruolo.'),
      mc('Una email del «direttore» che chiede un bonifico urgente a un nuovo IBAN è tipicamente:', ['BEC', 'Smishing', 'Ransomware', 'Un aggiornamento legittimo'], 0, 'Business Email Compromise.'),
      mc('Quale leva psicologica usa «entro un\'ora il tuo account sarà sospeso»?', ['Urgenza e paura', 'Reciprocità', 'Curiosità', 'Conformità sociale'], 0, 'Spinge ad agire senza riflettere.'),
      mc('Nel link «banca.example.com.sito-falso.net/login» il vero dominio è:', ['sito-falso.net', 'banca.example.com', 'example.com', 'login'], 0, 'Il dominio si legge dalla fine, prima del percorso.'),
      order('Ordina la reazione a un messaggio sospetto', ['non cliccare', 'verifica con altro canale', 'segnala', 'elimina'], 'Verifica e segnalazione prima di eliminare.'),
      mc('Una buona difesa contro la truffa del cambio IBAN è:', ['Conferma telefonica al numero già noto', 'Rispondere alla email', 'Usare il numero nel messaggio', 'Pagare subito per non perdere lo sconto'], 0, 'Verifica per un canale indipendente.'),
      mc('Perché una MFA FIDO2 aiuta contro il phishing?', ['Non funziona su un dominio falso', 'Nasconde l\'email', 'Blocca gli SMS', 'Cifra gli allegati'], 0, 'Credenziale legata al dominio.'),
      fill('La telefonata fraudolenta che si spaccia per la banca è un attacco di ...', ['vishing'], 'Voice phishing.'),
      mc('Quale pratica è corretta in una simulazione di phishing?', ['Spiegare subito che era un test e non raccogliere credenziali reali', 'Pubblicare la lista di chi ha cliccato', 'Usare notizie su licenziamenti reali', 'Raccogliere le password digitate'], 0, 'Obiettivo formativo e rispettoso.'),
      mc('Quale approccio promuove la segnalazione tempestiva?', ['Ringraziare chi segnala anche se ha sbagliato', 'Punire chi clicca', 'Nascondere i casi', 'Evitare ogni formazione'], 0, 'Una cultura senza colpa fa emergere prima gli incidenti.')
    ],
    test: [
      mc('Un attacco BEC è difficile da fermare con i filtri perché spesso:', ['Non contiene link né allegati', 'Usa solo immagini incorporate', 'Arriva sempre in orario notturno', 'È cifrato dal mittente'], 0, 'Il testo da solo è la minaccia.'),
      mc('Un codice QR che porta a un sito falso è un caso di:', ['Quishing', 'Vishing', 'Smishing vocale', 'Whaling'], 0, 'Phishing tramite QR.'),
      mc('Hai cliccato un link sospetto e inserito la password. La prima azione utile è:', ['Cambiare la password dal sito vero e avvisare IT', 'Aspettare qualche giorno', 'Eliminare il browser', 'Non dire nulla'], 0, 'Rapidità e trasparenza riducono il danno.'),
      mc('Il campo «Rispondi a» diverso dal mittente è:', ['Un segnale sospetto da verificare', 'Sempre normale nella posta aziendale', 'Una prova di autenticità del messaggio', 'Un errore del client di posta'], 0, 'Le risposte potrebbero andare all\'attaccante.'),
      mc('Quale segnale è più affidabile nei messaggi moderni?', ['Pressione a fare in fretta fuori procedura', 'Errori di ortografia', 'Presenza del logo', 'Lunghezza del testo'], 0, 'Gli errori possono mancare, la pressione no.'),
      order('Ordina le fasi dell\'ingegneria sociale', ['raccolta informazioni', 'pretesto', 'contatto', 'azione della vittima'], 'Dalla preparazione al risultato.'),
      fill('Il whaling è lo spear phishing rivolto ai ...', ['dirigenti', 'vertici', 'manager'], 'Bersagli di alto livello.')
    ]
  });

  /* ---------- 5 · Malware: concetti ---------- */
  C.addTopic({
    id: 'cyb-malware-concetti', subject: 'cyb', stage: 'L0', minutes: 12,
    title: 'Malware: tipi, ciclo di infezione e difese',
    summary: 'Famiglie di malware, fasi concettuali di un\'infezione, persistenza, segnali e difese (patching, EDR, backup 3-2-1).',
    objectives: ['Distinguere le principali famiglie di malware', 'Descrivere a livello concettuale le fasi di un\'infezione', 'Elencare difese e segnali di infezione, incluso il backup 3-2-1'],
    pages: [
      { h: 'Che cos\'è il malware', b: `**Malware** (malicious software) è qualsiasi software progettato per danneggiare, spiare o ottenere accessi non autorizzati. Si classifica in base a **come si diffonde** e a **cosa fa**; molti campioni combinano più caratteristiche.\n\nServe a:\n- ottenere **denaro** (ransomware, furto di dati bancari, mining abusivo);\n- **spiare** (credenziali, comunicazioni);\n- ottenere **controllo** del dispositivo, da usare in seguito;\n- **sabotare** o interrompere attività.\n\nUn punto utile: il malware **non è magia**. È codice che gira con i permessi dell'utente o del processo che lo esegue. Per questo contano molto i **permessi** (privilegio minimo), gli **aggiornamenti** (le vulnerabilità sfruttate) e il **comportamento dell'utente** (chi lo esegue).\n\nQuesta lezione è **concettuale e difensiva**: non contiene codice né istruzioni per realizzare malware, e non serve a questo. Servono a riconoscere, prevenire e rispondere.` },
      { h: 'Virus, worm, trojan', b: `Tre famiglie classiche, distinte dal **meccanismo di diffusione**.\n\n- **Virus**: si **attacca a un file o programma ospite** e si diffonde solo quando l'ospite viene eseguito o condiviso. Richiede quindi un'azione dell'utente.\n- **Worm** (verme): si **replica da solo attraverso la rete**, sfruttando vulnerabilità o servizi esposti, senza bisogno di ospite né di azioni dell'utente. Può saturare reti e sistemi molto in fretta.\n- **Trojan** (cavallo di Troia): si presenta come **software utile o legittimo** (un crack, un finto aggiornamento, un'app contraffatta) ma contiene una funzione nascosta. **Non si replica da solo**: è l'utente a installarlo.\n\n> Un «convertitore PDF gratuito» scaricato da un sito sconosciuto che installa anche un programma che spia le password: un trojan.\n\nNella terminologia comune si usa spesso «virus» come sinonimo di malware: tecnicamente è **una** categoria, non tutte.` },
      { h: 'Ransomware, spyware, rootkit', b: `Famiglie definite da **ciò che fanno**.\n\n- **Ransomware**: **cifra i file** della vittima (o li ruba) e chiede un **riscatto**. Nella **doppia estorsione** minaccia anche di pubblicare i dati rubati. Pagare non garantisce il recupero e finanzia i criminali; le autorità sconsigliano il pagamento.\n- **Spyware**: raccoglie di nascosto informazioni (cronologia, schermate, digitazioni). Il **keylogger** registra quanto si digita; l'**infostealer** ruba password salvate e cookie di sessione.\n- **Rootkit**: nasconde la presenza di altro malware e mantiene accessi privilegiati, intervenendo a basso livello del sistema. Difficile da individuare e da rimuovere: spesso la soluzione è **reinstallare** il sistema.\n- **Adware** e **cryptojacker** sfruttano pubblicità e potenza di calcolo.\n\n> Un PC che improvvisamente mostra file rinominati con un'estensione strana e una nota di riscatto: sintomi di ransomware.\n\nLa risposta immediata a un ransomware: **isolare** il dispositivo dalla rete e avvisare chi gestisce la sicurezza.` },
      { h: 'Botnet e controllo remoto', b: `Una **botnet** è una rete di dispositivi infetti (bot o «zombie») controllati a distanza da un operatore tramite un'infrastruttura di **comando e controllo** (C2).\n\nGli usi tipici:\n- attacchi **DDoS**: migliaia di dispositivi inviano traffico insieme per rendere un servizio indisponibile;\n- invio di **spam** e phishing;\n- **furto** e uso abusivo di risorse;\n- punto d'appoggio per ulteriori intrusioni.\n\nI bot non sono solo PC: telecamere IP, router e dispositivi IoT con **password predefinite** o firmware non aggiornato sono bersagli frequenti.\n\n> Una telecamera domestica con la password di fabbrica può partecipare a un attacco senza che il proprietario se ne accorga.\n\nUn **RAT** (remote access trojan) dà all'operatore il controllo diretto del singolo dispositivo.\n\nDifese concrete: cambiare le credenziali predefinite, aggiornare il firmware, non esporre dispositivi su Internet senza necessità, segmentare i dispositivi IoT su una rete separata.` },
      { h: 'Le fasi di un\'infezione (concetto)', b: `Descritta in modo generale, un'infezione segue spesso queste fasi.\n\n1. **Consegna**: il codice arriva alla vittima: allegato, link, chiavetta, sito compromesso, software contraffatto, catena di fornitura.\n2. **Esecuzione**: qualcuno o qualcosa lo avvia, spesso con **un clic dell'utente** o sfruttando una vulnerabilità non corretta.\n3. **Persistenza**: si assicura di sopravvivere al riavvio.\n4. **Contatto con l'esterno**: si collega a un server di controllo per ricevere istruzioni.\n5. **Movimento laterale e furto di privilegi**: cerca di estendersi ad altri sistemi e di ottenere permessi maggiori.\n6. **Azione sull'obiettivo**: cifratura, furto di dati, sabotaggio.\n\n> Allegato Office con macro → esecuzione → servizio di avvio → collegamento a un server → diffusione nella rete → cifratura dei file.\n\nOgni fase è un'**occasione per fermare** l'attacco: filtri email, aggiornamenti, EDR, segmentazione di rete, monitoraggio. Più presto si interrompe la catena, minore è il danno.` },
      { h: 'Persistenza e segnali di infezione', b: `La **persistenza** è la capacità del malware di restare attivo dopo il riavvio o la chiusura del programma, per esempio inserendosi tra i programmi avviati automaticamente, tra le attività pianificate o tra i servizi. Per chi difende è utile perché lascia **tracce controllabili**: gli strumenti di sicurezza e gli amministratori controllano elenchi di avvio e attività pianificate anomale.\n\nSegnali di una possibile infezione:\n- computer o rete **insolitamente lenti**, ventole sempre al massimo;\n- programmi, estensioni del browser o **home page** modificati senza motivo;\n- finestre pubblicitarie, **antivirus disattivato** che non si riattiva;\n- file inaccessibili, rinominati o cifrati, con **nota di riscatto**;\n- **traffico di rete** insolito, connessioni verso destinazioni sconosciute;\n- account che inviano messaggi non scritti dall'utente;\n- avvisi di accessi da luoghi inattesi.\n\nNessun segnale è conclusivo da solo: possono avere cause banali. In caso di dubbio **isola il dispositivo** e fai analizzare da chi ne ha competenza.` },
      { h: 'Difese e backup 3-2-1', b: `Difese principali, in strati.\n\n- **Aggiornamenti** (patching) di sistema e applicazioni: chiudono le vulnerabilità sfruttate.\n- **Privilegio minimo**: account ordinari senza diritti di amministratore; limita l'azione del malware.\n- **EDR/antimalware** aggiornati, che rilevano **comportamenti** sospetti e permettono l'isolamento del dispositivo.\n- **Filtri email e web**, blocco delle macro non necessarie.\n- **Segmentazione di rete** per limitare la diffusione.\n- **Software solo da fonti ufficiali**.\n- **Formazione** degli utenti.\n\n**Backup 3-2-1**: almeno **3** copie dei dati, su **2** tipi di supporto diversi, con **1** copia **fuori sede**. Oggi si aggiunge spesso una copia **offline o immutabile**, che il ransomware non può cifrare, e soprattutto si **testa il ripristino**: un backup mai provato è solo una speranza.\n\n> Un ransomware cifra il server: con un backup offline testato si ripristina in ore, senza trattare con i criminali.` }
    ],
    exercises: [
      mc('Quale malware si replica da solo attraverso la rete senza azione dell\'utente?', ['Worm', 'Virus', 'Trojan', 'Adware'], 0, 'Il worm si autodiffonde.'),
      mc('Un programma «gratuito» che contiene una funzione nascosta dannosa è un:', ['Trojan', 'Worm', 'Rootkit', 'Bot'], 0, 'Si presenta come legittimo.'),
      mc('Il malware che cifra i file e chiede un riscatto è:', ['Ransomware', 'Spyware', 'Rootkit', 'Adware'], 0, 'Estorsione tramite cifratura.'),
      mc('Che cosa registra un keylogger?', ['Quello che si digita', 'Il traffico del router', 'La temperatura della CPU', 'Le ricevute dei pagamenti'], 0, 'È una forma di spyware.'),
      mc('Quale malware è progettato per nascondere altri programmi dannosi e mantenere privilegi?', ['Rootkit', 'Adware', 'Virus semplice', 'Worm'], 0, 'Agisce a basso livello.'),
      mc('Una botnet è usata tipicamente per:', ['Attacchi DDoS e invio di spam', 'Aggiornare l\'antivirus dei computer', 'Eseguire i backup pianificati dei dati', 'Firmare documenti elettronici'], 0, 'Molti dispositivi controllati insieme.'),
      order('Ordina le fasi concettuali di un\'infezione', ['consegna', 'esecuzione', 'persistenza', 'contatto con il controllo', 'azione sull\'obiettivo'], 'Dalla diffusione all\'effetto finale.'),
      fill('Nel backup 3-2-1 la copia fuori sede è la numero ...', ['1', 'uno'], 'Tre copie, due supporti, una fuori sede.'),
      mc('Perché un backup deve essere testato?', ['Per essere certi che il ripristino funzioni', 'Per aumentare lo spazio', 'Per cifrare i file', 'Per disattivare l\'EDR'], 0, 'Un backup mai provato può fallire.'),
      mc('Per un dispositivo sospetto di ransomware, la prima mossa è:', ['Isolarlo dalla rete e avvisare la sicurezza', 'Pagare il riscatto', 'Continuare a lavorare', 'Collegarlo a un altro PC'], 0, 'Si limita la diffusione.'),
      mc('Quale fa parte delle difese contro il malware?', ['Installare software solo da fonti ufficiali', 'Usare sempre un account amministratore', 'Disattivare gli aggiornamenti automatici', 'Aprire ogni allegato ricevuto per posta'], 0, 'Riduce il rischio di trojan.')
    ],
    test: [
      mc('Qual è la differenza tra virus e worm?', ['Il virus ha bisogno di un ospite, il worm si diffonde da solo', 'Il worm richiede sempre un clic', 'Il virus non esiste', 'Sono identici'], 0, 'Meccanismi di diffusione diversi.'),
      mc('Nella doppia estorsione il ransomware:', ['Cifra i dati e minaccia di pubblicare quelli rubati', 'Solo cancella i backup', 'Solo mostra pubblicità', 'Aggiorna il sistema'], 0, 'Due leve di pressione.'),
      mc('Una telecamera IP con password di fabbrica può diventare:', ['Parte di una botnet', 'Un firewall', 'Un gestore di password', 'Un backup'], 0, 'Dispositivi IoT trascurati sono bersagli frequenti.'),
      mc('Quale elemento limita maggiormente i danni se un utente esegue un file dannoso?', ['Un account senza diritti di amministratore', 'Una password breve', 'Un monitor più grande', 'Un cavo diverso'], 0, 'Il malware eredita i permessi.'),
      mc('Quale caratteristica ha una copia di backup «immutabile» o offline?', ['Il ransomware non può modificarla', 'È sempre più veloce da ripristinare rispetto alle altre', 'Non richiede alcuna prova periodica di ripristino', 'Non può essere ripristinata'], 0, 'È fuori dalla portata del malware.'),
      order('Ordina i livelli di una difesa antimalware', ['filtri email', 'patching', 'EDR', 'backup testato'], 'Dal primo ostacolo al ripristino.'),
      fill('Il software che rende persistente la presenza di altro malware e si nasconde a basso livello è un ...', ['rootkit', 'Rootkit'], 'Rootkit.')
    ]
  });

  /* ---------- 6 · Etica, legge e autorizzazione ---------- */
  C.addTopic({
    id: 'cyb-etica-legge-e-autorizzazione', subject: 'cyb', stage: 'L0', minutes: 12,
    title: 'Etica, legge e autorizzazione',
    summary: 'Autorizzazione e perimetro, divulgazione responsabile, bug bounty, principi legali, regole d\'ingaggio, codici etici e laboratori sicuri.',
    objectives: ['Spiegare perché senza autorizzazione esplicita un accesso è illecito', 'Descrivere divulgazione coordinata, bug bounty e regole d\'ingaggio', 'Praticare solo in ambienti propri o appositamente predisposti'],
    pages: [
      { h: 'Autorizzazione e perimetro (scope)', b: `La differenza tra un professionista della sicurezza e un criminale non sta nelle tecniche, ma nell'**autorizzazione**.\n\nUn'attività è lecita solo se ha:\n- il **permesso esplicito**, preferibilmente scritto, di chi ha l'autorità sul sistema;\n- un **perimetro** (scope) chiaro: quali sistemi, indirizzi, applicazioni, orari e metodi sono inclusi, e quali **esclusi**;\n- **limiti** su ciò che si può fare e su come trattare i dati incontrati.\n\n> Avere la password di un amico non significa avere il permesso di entrare ovunque nel suo account. «Era facile» o «volevo solo vedere» non sono autorizzazioni.\n\nQuesto vale anche per un sito che sembra protetto male: la **debolezza** di un sistema non è un invito. Anche se non si causano danni e le intenzioni sono buone, **accedere senza permesso resta illecito**.\n\nIn caso di dubbio la regola è semplice: **chiedi prima**, ottieni il consenso scritto, resta nel perimetro.` },
      { h: 'Perché l\'accesso non autorizzato è illegale', b: `Quasi tutti gli ordinamenti puniscono l'accesso non autorizzato a sistemi informatici. I principi generali sono comuni.\n\n- **Il sistema appartiene a qualcuno**, che ha diritto di decidere chi vi entra, come per un domicilio fisico.\n- Contano **l'accesso e il superamento dei limiti** concessi, anche se non si causano danni.\n- Sono puniti anche la **detenzione e diffusione abusiva di credenziali** e di strumenti pensati per danneggiare sistemi, l'**intercettazione** di comunicazioni e il **danneggiamento** di dati.\n- Gravi se riguardano sistemi **pubblici o critici**, o dati **personali**.\n\nIn **Italia** il Codice penale contiene norme specifiche sull'accesso abusivo a sistemi informatici e sui reati informatici correlati, e vi si affianca la disciplina sulla **protezione dei dati personali** (GDPR). A livello europeo e internazionale esistono convenzioni che armonizzano i reati informatici.\n\nQuesta lezione non è consulenza legale: per un caso concreto serve un professionista. Il principio pratico è però semplice: **senza autorizzazione, non si accede**.` },
      { h: 'Divulgazione responsabile e coordinata', b: `Chi scopre una vulnerabilità, per esempio un ricercatore, un cliente o un utente, ha una scelta di comportamento.\n\nLa **divulgazione responsabile** (responsible disclosure) o **coordinata** (CVD) prevede:\n1. **limitare** il più possibile l'esplorazione, senza accedere ai dati altrui né danneggiare;\n2. **segnalare in privato** al responsabile: indirizzo di sicurezza, pagina dedicata o file **security.txt**;\n3. fornire **dettagli sufficienti** per riprodurre e correggere il problema;\n4. concedere un **tempo ragionevole** per la correzione (spesso 90 giorni, con eccezioni);\n5. **pubblicare** i dettagli solo dopo la correzione o alla scadenza concordata, eventualmente con l'aiuto di un coordinatore come un CERT.\n\nNon vanno **mai** fatti: sfruttare la falla per profitto, copiare i dati «come prova», minacciare di divulgare per ottenere denaro, pubblicare dettagli prima di avvisare.\n\n> La vulnerabilità ha un identificativo **CVE** e una valutazione di gravità (punteggio **CVSS**), usati per tracciare e correggere i problemi.` },
      { h: 'Bug bounty e programmi di vulnerability disclosure', b: `Molte organizzazioni pubblicano regole con cui invitano a cercare vulnerabilità.\n\n- **VDP** (vulnerability disclosure policy): indica come segnalare e garantisce, a certe condizioni, di non agire contro chi segue le regole. Può non prevedere compensi.\n- **Bug bounty**: programma con **ricompense** in denaro o riconoscimenti per le segnalazioni valide, spesso su piattaforme dedicate.\n\nOgni programma ha le sue **regole**:\n- **ambito** (in scope e fuori scope);\n- tecniche **vietate** (per esempio attacchi di negazione del servizio, social engineering contro i dipendenti, accesso a dati di altri utenti);\n- formato della segnalazione e **tempi** di risposta;\n- eventuale protezione legale (**safe harbor**) e limiti.\n\n> Se un sito pubblica un programma ma il tuo test riguarda un dominio **fuori scope**, la protezione non vale.\n\nUsare un account di prova **tuo** e ridurre al minimo i dati toccati è la prassi. Il bug bounty **non è una licenza** generale: vale solo entro le regole scritte.` },
      { h: 'Regole d\'ingaggio e attività professionali', b: `Un **test di sicurezza autorizzato** (per esempio un penetration test) si svolge con un accordo formale. Le **regole d'ingaggio** (rules of engagement) definiscono:\n\n- **obiettivi** e **perimetro** dei sistemi;\n- **periodo e orari** consentiti;\n- tecniche **ammesse e vietate** (per esempio niente attacchi che interrompano la produzione);\n- **contatti** di emergenza e procedura se si causa un problema o se si trova una compromissione preesistente;\n- gestione e **riservatezza** dei dati incontrati, e di cosa va cancellato a fine incarico;\n- formato del **rapporto** e conservazione delle prove;\n- **responsabilità** e assicurazione.\n\nIn caso di dubbio o di scoperta imprevista, ci si **ferma e si avvisa il committente**.\n\n> Se durante un test autorizzato si scopre che un sistema fuori perimetro è esposto, non lo si esplora: si segnala.\n\nL'autorizzazione deve venire da chi **ne ha il potere**: un tecnico non può autorizzare il test di sistemi di un cliente o di un fornitore cloud senza le necessarie intese.` },
      { h: 'Codici etici e deontologia', b: `Le professioni della sicurezza hanno codici di condotta, per esempio quelli di **(ISC)²**, **ISACA** e **ACM**. I principi ricorrenti sono:\n\n- **proteggere** la società, il bene comune e l'infrastruttura;\n- agire con **onestà, integrità e correttezza**;\n- **competenza**: accettare solo incarichi che si è in grado di svolgere;\n- **riservatezza** su informazioni di clienti e persone incontrate nel lavoro;\n- **minimizzare i danni** e rispettare la privacy;\n- **responsabilità** verso chi viene colpito dalle proprie azioni;\n- evitare **conflitti di interesse** e dichiararli;\n- far progredire la professione, condividendo le conoscenze in modo responsabile.\n\n> Un tecnico scopre per caso la cartella di un collega con dati sanitari: non la legge, non la copia, la segnala e fa correggere i permessi.\n\nL'etica non si esaurisce nel rispettare la legge: ciò che è legale può essere comunque scorretto, e le scelte vanno guidate anche dall'**effetto sulle persone**.` },
      { h: 'Laboratori sicuri: dove esercitarsi', b: `Per imparare si pratica, ma **solo dove è lecito**.\n\nAmbienti adatti:\n- **dispositivi di tua proprietà** e reti di casa tue, con il consenso di chi ne condivide l'uso;\n- **macchine virtuali** su una rete isolata (solo host o interna) create da te, per esempio con sistemi didattici apposta vulnerabili;\n- **piattaforme di formazione** e laboratori online che dichiarano espressamente di consentire la pratica;\n- **competizioni CTF** con regole pubbliche;\n- ambienti **di test aziendali** con autorizzazione scritta.\n\nBuone abitudini:\n- tieni il laboratorio **isolato** dalla rete di casa e dai dati personali;\n- usa **istantanee** (snapshot) per tornare indietro;\n- non testare mai servizi di terzi, dei vicini o «un sito qualsiasi» per allenarti;\n- **documenta** ciò che fai.\n\n> Un sistema didattico volutamente vulnerabile non va mai collegato direttamente a Internet.\n\nIn caso di dubbio sulla liceità di un'attività, **non farla**, chiedi a un docente o a un responsabile.` }
    ],
    exercises: [
      mc('Che cosa rende lecita un\'attività di test di sicurezza?', ['Un\'autorizzazione esplicita entro un perimetro definito', 'Le buone intenzioni di chi esegue il test', 'L\'assenza di danni ai sistemi sottoposti al test', 'Il fatto che il sistema sia debole e facile da raggiungere'], 0, 'Senza permesso resta accesso non autorizzato.'),
      mc('Trovi per caso una falla in un sito. La condotta corretta è:', ['Segnalarla in privato al responsabile senza sfruttarla', 'Pubblicarla subito sui social per avvisare gli utenti', 'Copiare alcuni dati come prova della sua esistenza', 'Chiedere un compenso al gestore in cambio del silenzio'], 0, 'È la divulgazione responsabile.'),
      mc('Che cos\'è lo scope di un programma di test?', ['L\'elenco di ciò che è incluso ed escluso dal test', 'Il compenso massimo previsto per il tester incaricato', 'Il nome ufficiale dell\'azienda che commissiona il test', 'La velocità di rete disponibile per svolgere il test'], 0, 'Il perimetro autorizzato.'),
      fill('Il file in cui un sito indica come segnalare problemi di sicurezza si chiama security.', ['txt'], 'security.txt (standard RFC 9116).'),
      order('Ordina una divulgazione coordinata', ['scoperta', 'segnalazione privata', 'correzione', 'pubblicazione'], 'I dettagli si pubblicano dopo la correzione.'),
      mc('Un bug bounty è:', ['Un programma che premia segnalazioni valide entro regole scritte', 'Un permesso generale di testare qualsiasi sito aperto al pubblico', 'Un tipo di malware che si diffonde tramite le estensioni dei browser', 'Una sanzione prevista per chi trova difetti nei sistemi altrui'], 0, 'Vale solo nei limiti del programma.'),
      mc('Durante un test autorizzato trovi un sistema fuori perimetro esposto. Cosa fai?', ['Non lo esplori e lo segnali al committente', 'Lo analizzi comunque, visto che è esposto', 'Pubblichi subito la sua esistenza in rete', 'Lo usi come appoggio per proseguire il test'], 0, 'Fuori perimetro non si agisce.'),
      mc('Quale luogo è adatto per esercitarsi?', ['Una macchina virtuale isolata creata da te', 'Il sito della tua scuola, di nascosto nel pomeriggio', 'La rete domestica di un vicino di casa', 'Un sito qualsiasi trovato online per caso'], 0, 'Ambiente proprio e isolato.'),
      mc('Quale principio etico è tipico dei codici professionali?', ['Riservatezza e minimizzazione dei danni', 'Vendere le falle al migliore offerente', 'Dichiarare le competenze che non si hanno', 'Ignorare i conflitti di interesse'], 0, 'Responsabilità verso persone e società.'),
      mc('Che cosa sono le regole d\'ingaggio?', ['Le condizioni concordate di un test: obiettivi, tempi, limiti, contatti', 'Un malware che si installa durante una verifica di sicurezza', 'Un tipo di backup eseguito prima di ogni test autorizzato', 'Il listino prezzi dell\'antivirus scelto dal committente'], 0, 'Documento formale prima di iniziare.'),
      fill('L\'identificativo pubblico che cataloga una vulnerabilità nota è il ...', ['CVE', 'cve'], 'Common Vulnerabilities and Exposures.')
    ],
    test: [
      mc('Un accesso senza permesso a un sistema debole, senza danni, è:', ['Comunque illecito', 'Lecito perché non c\'è danno', 'Lecito se il sistema è debole', 'Lecito se lo si dichiara dopo'], 0, 'Conta l\'assenza di autorizzazione.'),
      mc('Quale comportamento è inaccettabile dopo aver trovato una falla?', ['Minacciare di divulgarla per ottenere denaro', 'Segnalarla in privato al responsabile del sistema', 'Concedere al produttore il tempo per correggerla', 'Passare per un coordinatore CERT per la segnalazione'], 0, 'È estorsione, non divulgazione responsabile.'),
      mc('Un programma VDP senza compensi serve a:', ['Indicare come segnalare problemi e con quali garanzie', 'Pagare in denaro ogni falla che viene segnalata', 'Autorizzare in anticipo qualsiasi tipo di test', 'Vendere a terzi i dati raccolti durante le segnalazioni'], 0, 'Regole di segnalazione.'),
      mc('Perché un laboratorio vulnerabile va isolato?', ['Per non esporlo né a Internet né ai dati personali', 'Per rendere più veloce il PC usato per gli esercizi', 'Per cancellare in automatico i log delle esercitazioni', 'Per evitare di dover installare gli aggiornamenti'], 0, 'È volutamente debole.'),
      mc('Chi può autorizzare un test su un sistema?', ['Chi ha l\'autorità sul sistema', 'Qualunque tecnico', 'Chiunque lo trovi interessante', 'Un amico'], 0, 'Serve il titolare dei diritti.'),
      order('Ordina i passi prima di un test autorizzato', ['accordo scritto', 'perimetro definito', 'regole d\'ingaggio', 'inizio del test'], 'Si parte solo con tutto formalizzato.'),
      fill('Il limite entro cui si può agire in un programma di test si chiama ...', ['scope', 'perimetro', 'Scope'], 'Ambito autorizzato.')
    ]
  });
})(window.ST = window.ST || {});
